import sys


def main():
    L = {}
    R = {}
    root = None
    out = []
    for line in sys.stdin.read().split('\n'):
        p = line.split()
        if not p:
            continue
        c = p[0]
        if c == 'insert':
            x = int(p[1])
            if root is None:
                root = x
                L[x] = None
                R[x] = None
                out.append('ok')
                continue
            n = root
            while True:
                if x == n:
                    out.append('dup')
                    break
                d = L if x < n else R
                if d[n] is None:
                    d[n] = x
                    L[x] = None
                    R[x] = None
                    out.append('ok')
                    break
                n = d[n]
        elif c == 'contains':
            x = int(p[1])
            n = root
            while n is not None and n != x:
                n = L[n] if x < n else R[n]
            out.append('yes' if n is not None else 'no')
        elif c == 'delete':
            x = int(p[1])
            par = None
            n = root
            while n is not None and n != x:
                par = n
                n = L[n] if x < n else R[n]
            if n is None:
                out.append('missing')
                continue
            if L[n] is not None and R[n] is not None:
                sp = n
                s = R[n]
                while L[s] is not None:
                    sp = s
                    s = L[s]
                # replace n by s: remove s from its place
                if sp == n:
                    R[n] = R[s]
                else:
                    L[sp] = R[s]
                L[s] = L[n]
                R[s] = R[n]
                rep = s
            else:
                rep = L[n] if L[n] is not None else R[n]
            if par is None:
                root = rep
            elif L[par] == n:
                L[par] = rep
            else:
                R[par] = rep
            del L[n]
            del R[n]
            out.append('ok')
        elif c == 'inorder':
            res = []
            st = []
            n = root
            while st or n is not None:
                while n is not None:
                    st.append(n)
                    n = L[n]
                n = st.pop()
                res.append(n)
                n = R[n]
            out.append(' '.join(map(str, res)) if res else '<empty>')
        elif c == 'height':
            h = 0
            lvl = [root] if root is not None else []
            while lvl:
                h += 1
                nxt = []
                for n in lvl:
                    if L[n] is not None:
                        nxt.append(L[n])
                    if R[n] is not None:
                        nxt.append(R[n])
                lvl = nxt
            out.append(str(h))
        elif c in ('min', 'max'):
            if root is None:
                out.append('empty')
            else:
                d = L if c == 'min' else R
                n = root
                while d[n] is not None:
                    n = d[n]
                out.append(str(n))
    print('\n'.join(out))


main()
